import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# Kernel for element-wise multiplication (a * b)
mul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mul_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] * b[idx];
    }
}
"""

# Custom CUDA function: elementwise division by Frobenius norm
elementwise_div_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

torch::Tensor elementwise_div_cuda(torch::Tensor x) {
    // Compute the global Frobenius norm using PyTorch (allowed as a helper)
    auto norm = torch.norm(x, p='fro');
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (x.numel() + block_size - 1) / block_size;

    // Create a temporary array filled with the scalar 1.0/norm
    float scale = (float)(1.0 / norm);
    float* b_ptr = new float[x.numel()];
    for (int i = 0; i < x.numel(); ++i) {
        b_ptr[i] = scale;
    }
    // Copy the scalar to device memory
    cudaMemcpy(b_ptr, &scale, sizeof(scale), cudaMemcpyHostToDevice);

    mul_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), b_ptr, out.data_ptr<float>(), x.numel());
    return out;
}
"""

# Compile the custom CUDA function
elementwise_div = load_inline(
    name="elementwise_div",
    cpp_sources=elementwise_div_cuda_source,
    cuda_sources=elementwise_div_cuda_source,
    functions=["elementwise_div_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_div = elementwise_div

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.elementwise_div(x)
